/*
 * OpenFPM build configuration header (config.h) for the Homebrew OpenFPM 5.0.1 package.
 *
 * OpenFPM's headers include "config.h", but the OpenFPM 5.0.1 install step does not copy it
 * into the installation prefix (neither the Homebrew bottles nor a source build contain it).
 * This copy was generated by OpenFPM's own CMake configure step (config/config_cmake.h.in)
 * with the options used by the abhinavsns/homebrew-openfpm formula. cpp/example.mk puts this
 * directory last on the include path, so a config.h shipped by OpenFPM itself takes precedence.
 */

/* OpenMP support */
#define HAVE_OPENMP

/* define if the Boost library is available */
#define HAVE_BOOST

/* define if the Boost::IOStreams library is available */
#define HAVE_BOOST_IOSTREAMS /**/

/* define if the Boost::PROGRAM_OPTIONS library is available */
#define HAVE_BOOST_PROGRAM_OPTIONS /**/

/* define if the Boost::Unit_Test_Framework library is available */
#define HAVE_BOOST_UNIT_TEST_FRAMEWORK /**/

/* define if the Boost::Context library is available */
#define HAVE_BOOST_CONTEXT /**/

/* define if the Boost::Fiber library is available */
#define HAVE_BOOST_FIBER /**/

/* Define if you have EIGEN library. */
#define HAVE_EIGEN

/* Defined if you have HDF5 support */
#define HAVE_HDF5

/* Define if you have LIBHILBERT library */
#define HAVE_LIBHILBERT 1

/* Define if you have METIS library */
#define HAVE_METIS 1

/* MPI Enabled */
#define HAVE_MPI

/* We have OSX */
#ifdef __APPLE__
#define HAVE_OSX
#endif

/* Define if you have PARMETIS library */
#define HAVE_PARMETIS 1

/* Define if you have PETSC library */
#define HAVE_PETSC

/* Define if you have SUITESPARSE library. */
#define HAVE_SUITESPARSE

/* Define to the sub-directory where libtool stores uninstalled libraries. */
#define LT_OBJDIR ".libs/"

/* Name of package */
#define PACKAGE "openfpm_pdata"

/* Define to the address where bug reports for this package should be sent. */
#define PACKAGE_BUGREPORT "BUG-REPORT-ADDRESS"

/* Define to the full name of this package. */
#define PACKAGE_NAME "OpenFPM_pdata"

/* Define to the full name and version of this package. */
#define PACKAGE_STRING "OpenFPM_pdata 1.0.0"

/* Define to the one symbol short name of this package. */
#define PACKAGE_TARNAME "openfpm_pdata"

/* Define to the home page for this package. */
#define PACKAGE_URL ""

/* Define to the version of this package. */
#define PACKAGE_VERSION "1.0.0"

/* Version number of package */
#define VERSION "1.0.0"
